        # orjson doesn't support all the same parameters as json.dumps
        if kwargs:
            raise TypeError('orjson does not accept the sort_keys parameter.' if 'sort_keys' in kwargs else f'orjson does not accept these parameters: {", ".join(kwargs.keys())}')
